    def replacement_db(self, table, changed, collision="rowid", swap=False):
        path = self.make_db()
        self.sql("DELETE FROM accounts", path=path)
        for row in ((1, "one", "a", 100), (2, "one", "b", 0),
                    (3, "two", "private", 456)):
            self.sql("INSERT INTO accounts(rowid,tenant,name,balance) VALUES (?,?,?,?)",
                     row, path=path)
        historical = ("two", "old", "private", "saved", 7)
        for history_table in ("transfers", "audit"):
            self.sql(f"INSERT INTO {history_table}(rowid,tenant,key,source,target,amount) "
                     "VALUES (3,?,?,?,?,?)", historical, path=path)
        if table == "accounts":
            columns, values = "tenant,name,balance", f"'two','private',{457 if changed else 456}"
        else:
            columns = "tenant,key,source,target,amount"
            values = f"'two','old','private','saved',{8 if changed else 7}"
        restore = ""
        if swap:
            spare = ("'two','spare',789" if table == "accounts"
                     else "'two','spare','private','saved',9")
            self.sql(f"INSERT INTO {table}(rowid,{columns}) VALUES (4,{spare})", path=path)
            restore = f"INSERT OR REPLACE INTO {table}(rowid,{columns}) VALUES (3,{spare});"
        if collision == "rowid":
            columns, values = f"rowid,{columns}", f"{4 if swap else 3},{values}"
        self.sql("CREATE TRIGGER existing AFTER INSERT ON audit BEGIN "
                 f"INSERT OR REPLACE INTO {table}({columns}) VALUES ({values}); {restore} END", path=path)
        return path, dict(zip(("tenant", "key", "source", "target", "amount"), historical))

    def test_replacement_rowid_swaps_preserve_values_via_api_and_cli(self):
        for table in TABLES:
            for interface in ("api", "cli"):
                with self.subTest(table=table, interface=interface):
                    path, historical = self.replacement_db(table, False, swap=True)
                    before = self.snapshot(path)
                    schema = self.sql("SELECT type,name,tbl_name,sql FROM sqlite_master ORDER BY name",
                                      path=path)
                    receipt = dict(tenant="one", key="k", source="a", target="b", amount=10)
                    if interface == "api":
                        self.assertEqual(vault.transfer(path, **receipt), receipt)
                    else:
                        self.assert_cli_success(self.cli(dict(op="transfer", **receipt), path), receipt)
                    expected = before.copy()
                    expected["accounts"] = before["accounts"].copy()
                    expected["accounts"].subtract({(b"one", b"a", 100): 1, (b"one", b"b", 0): 1})
                    expected["accounts"].update({(b"one", b"a", 90): 1, (b"one", b"b", 10): 1})
                    for history_table in ("transfers", "audit"):
                        expected[history_table] = before[history_table].copy()
                        expected[history_table].update([(b"one", b"k", b"a", b"b", 10)])
                    self.assertEqual(self.snapshot(path), expected)
                    identity = "name" if table == "accounts" else "key"
