                        f"SELECT rowid,{identity} FROM {table} WHERE tenant='two' ORDER BY rowid",
                        path=path,
                    ), [(3, "spare"), (4, "private" if table == "accounts" else "old")])
                    self.assertEqual(self.sql(
                        "SELECT type,name,tbl_name,sql FROM sqlite_master ORDER BY name", path=path,
                    ), schema)
                    self.assert_history_replays(path, [historical, receipt])

